// Kullanım
<Card>
  <Card.Header>Başlık</Card.Header>
  <Card.Body>İçerik</Card.Body>
  <Card.Footer>Alt bilgi</Card.Footer>
</Card>

// Implementasyon
const Card = ({ children }: { children: ReactNode }) => (
  <View style={styles.card}>{children}</View>
);
Card.Header = ({ children }: { children: ReactNode }) => (
  <View style={styles.header}>{children}</View>
);
Card.Body = ({ children }: { children: ReactNode }) => (
  <View style={styles.body}>{children}</View>
);
Card.Footer = ({ children }: { children: ReactNode }) => (
  <View style={styles.footer}>{children}</View>
);

interface RenderPropsProps<T> {
  data: T[];
  render: (item: T, index: number) => ReactNode;
}

const RenderProps = <T,>({ data, render }: RenderPropsProps<T>) => (
  <FlatList
    data={data}
    renderItem={({ item, index }) => render(item, index)}
    keyExtractor={(item, index) => index.toString()}
  />
);

interface ToggleProps {
  isOn: boolean;
  onToggle: (isOn: boolean) => void;
}

const Toggle = ({ isOn, onToggle }: ToggleProps) => (
  <TouchableOpacity
    style={[styles.toggle, isOn && styles.toggleOn]}
    onPress={() => onToggle(!isOn)}
  />
);

import { useWindowDimensions } from 'react-native';

const ResponsiveContainer = ({ children }: { children: ReactNode }) => {
  const { width, height } = useWindowDimensions();
  const isTablet = width >= 768;

  return (
    <View style={[
      styles.container,
      isTablet && styles.tabletContainer
    ]}>
      {children}
    </View>
  );
};

import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';

const SafeScreen = ({ children }: { children: ReactNode }) => {
  const insets = useSafeAreaInsets();

  return (
    <SafeAreaView style={styles.container} edges={['top', 'bottom']}>
      <View style={{ paddingBottom: insets.bottom }}>
        {children}
      </View>
    </SafeAreaView>
  );
};

const FadeInView = ({ children }: { children: ReactNode }) => {
  const fadeAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 300,
      useNativeDriver: true,
    }).start();
  }, []);

  return (
    <Animated.View style={{ opacity: fadeAnim }}>
      {children}
    </Animated.View>
  );
};

import { PanGestureHandler } from 'react-native-gesture-handler';

const DraggableCard = () => {
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);

  const gesture = Gesture.Pan()
    .onUpdate((event) => {
      translateX.value = event.translationX;
      translateY.value = event.translationY;
    });

  return (
    <GestureDetector gesture={gesture}>
      <Animated.View style={[
        styles.card,
        { transform: [{ translateX }, { translateY }] }
      ]} />
    </GestureDetector>
  );
};

const useMediaQuery = (minWidth: number) => {
  const { width } = useWindowDimensions();
  return width >= minWidth;
};

// Kullanım
const isTablet = useMediaQuery(768);

const useTheme = () => {
  const isDark = useColorScheme() === 'dark';

  return useMemo(() => ({
    colors: {
      background: isDark ? '#1a1a1a' : '#ffffff',
      text: isDark ? '#ffffff' : '#1a1a1a',
      primary: '#6366f1',
    },
    isDark,
  }), [isDark]);
};

interface FormFieldProps {
  label: string;
  value: string;
  onChangeText: (text: string) => void;
  placeholder?: string;
  error?: string;
}

const FormField = ({
  label,
  value,
  onChangeText,
  placeholder,
  error,
}: FormFieldProps) => (
  <View style={styles.field}>
    <Text style={styles.label}>{label}</Text>
    <TextInput
      style={[styles.input, error && styles.inputError]}
      value={value}
      onChangeText={onChangeText}
      placeholder={placeholder}
      accessibilityLabel={label}
    />
    {error && <Text style={styles.error}>{error}</Text>}
  </View>
);
